import ast, pathlib

# Focus only on files changed in progressive-fixes
changed_files = [
    'nanobot/cli/commands.py',
    'nanobot/groupchat/display/display.py',
    'nanobot/groupchat/history/history_settings.py',
    'nanobot/groupchat/history/prompt_builder.py',
    'nanobot/groupchat/history/tool_pruning.py',
    'nanobot/groupchat/orchestra/broadcast.py',
    'nanobot/groupchat/orchestra/engine.py',
    'nanobot/groupchat/orchestra/mailbox.py',
    'nanobot/groupchat/orchestra/tools/chatroom_tools.py',
    'nanobot/groupchat/orchestra/tools/tool_loop.py',
    'nanobot/providers/httpx_provider.py',
    'nanobot/security/network.py',
    'nanobot/skills/loader.py',
]

issues = []
for fp in changed_files:
    p = pathlib.Path(fp)
    if not p.exists():
        continue
    source = p.read_text()
    tree = ast.parse(source, filename=str(p))

    # Unused imports
    imports = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                name = alias.asname or alias.name
                if not name.startswith('_'):
                    imports[name] = node.lineno
        elif isinstance(node, ast.ImportFrom):
            for alias in node.names:
                name = alias.asname or alias.name
                if not name.startswith('_'):
                    imports[name] = node.lineno

    lines = source.split('\n')
    for name, line in imports.items():
        count = sum(1 for l in lines if name in l) - 1
        if count <= 0:
            issues.append(('unused-import', fp, line, name))

    # Bare except
    for node in ast.walk(tree):
        if isinstance(node, ast.ExceptHandler):
            if node.type is None:
                issues.append(('bare-except', fp, node.lineno, 'bare except'))

    # TODO/FIXME/HACK
    for i, line in enumerate(lines, 1):
        for tag in ['TODO', 'FIXME', 'HACK', 'XXX']:
            if tag in line and not line.strip().startswith('#'):
                pass
            elif tag in line:
                issues.append(('todo', fp, i, line.strip()[:80]))

for typ, fp, line, detail in issues:
    print(f'{typ:15s} {fp}:{line} {detail}')
print(f'--- Total issues in changed files: {len(issues)}')
