# Check test files for quality
import ast, pathlib

test_files = list(pathlib.Path('tests').rglob('*.py'))
issues = []
for tf in test_files:
    if not tf.exists():
        continue
    source = tf.read_text()
    # Check for empty/placeholder files
    if len(source.strip()) < 10:
        issues.append(f'PLACEHOLDER: {tf} (only {len(source.strip())} chars)')
    # Check for syntax errors
    try:
        ast.parse(source)
    except SyntaxError as e:
        issues.append(f'SYNTAX-ERROR: {tf}:{e.lineno} {e.msg}')
    # Check for no actual test functions
    tree = ast.parse(source)
    has_test = False
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if node.name.startswith('test_'):
                has_test = True
                break
    if not has_test and len(source.strip()) > 10:
        issues.append(f'NO-TESTS: {tf}')

for issue in issues:
    print(issue)
if not issues:
    print('Test files look clean.')
